insert into Hotel ([Name], [Address], [Description], [DistanceToCoastline], [ImgId], [Price]) VALUES
('Hilton Miami Downtown',
 '3755 NW 78th Avenue, Doral, Маямі, FL 33166, США',
 'Цей першокласний готель з прямим сполученням зі станцією наземного метро Mover розташований у центрі Маямі, на березі затоки Біскейн. До послуг гостей басейн на даху, добре обладнаний тренажерний зал та просторі номери.\nЕлегантні номери готелю Hilton Miami Downtown вирізняються вікнами від підлоги до стелі. З деяких номерів відкривається панорамний вид на затоку Біскейн. Серед стандартних зручностей – телевізор із плоским 27-дюймовим екраном, док-станція для MP3 і кавоварка.\nУ готелі Miami Hilton надаються послуги консьєржа, а також оренди автомобілів. Окрім того, гості зможуть вільно користуватися усіма зручностями бізнес-центру.\nНа території готелю Hilton Downtown Miami працює бістро Brisa, де подають страви місцевої та інтернаціональної кухні. Гості зможуть насолодитися трапезою в приміщенні або на відкритому повітрі в патіо. У барі The Gallery та в барі біля басейну пропонують різноманітні напої.\nВідстань від готелю Hilton Miami Downtown до міжнародного аеропорту Майамі становить 12,1 км, а до порту Майамі – 3,4 км.',
 410, 1, 24000000),
('La Quinta by Wyndham Miami Airport East',
 '3501 Northwest 42nd Avenue (Le Jeune Road), Маямі, FL 33142, США',
 'Цей готель у Флориді розташований у самому серці Маямі. До послуг гостей безкоштовний континентальний сніданок і відкритий басейн. Гості також можуть користуватися щоденним трансфером з/до аеропорту, який знаходиться лише за 3 км.\nУ всіх номерах є телевізор із плоским екраном і кабельними каналами та кавоварка. У готелі La Quinta Inn and Suites Miami Airport East є власна ванна кімната та праска.\nГості цього готелю Miami Airport La Quinta можуть скористатися безкоштовним Wi-Fi на всій території готелю. До послуг гостей пральня самообслуговування, приміщення для проведення засідань та безкоштовний трансфер з/до аеропорту.\nКультовий район ар-деко в Саут-Біч та дитячий музей-школа Маямі знаходяться за 16 км. Відстань до Університету Маямі також становить 13 км.',
 7650, 2, 24000000),
 ('Wingate by Wyndham',
  '3755 NW 78th Avenue, Doral, Маямі, FL 33166, США',
  'Готель Wingate by Wyndham Miami Airport розташований у Маямі. До послуг гостей безкоштовний Wi-Fi, фітнес-центр і безкоштовна парковка. На території готелю працюють 2 бари та пункт прокату автомобілів. У всіх номерах є мікрохвильова піч, невеликий холодильник та кавоварка. У власних ванних кімнатах надаються фен і безкоштовні туалетно-косметичні засоби. Також є телевізор.',
  13900, 3, 24000000)
